Q: Lowest common ancestor C++ A: <p>You are basically on the right track (though using templates is a little overkill for a beginner project). But, your code is incomplete. It does not compile properly (<code>curr</code> is undefined inside of <code>findLCA())</code>, and it does not have a <code>main()</code> function that actually uses your <code>BST</code> class.</p>
<p>Try something like this:</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;iostream&gt;

using namespace std;

template &lt;typename T&gt;
class BTNode {
private:
    T data;
    BTNode&lt;T&gt; *left = nullptr, *right = nullptr;

public:
    BTNode(const T&amp; d) : data(d) {}

    ~BTNode() {
        delete left;
        delete right;
    }

    T getData() {
        return data;
    }

    BTNode&lt;T&gt;* getLeft(){
        return left;
    }

    BTNode&lt;T&gt;* getRight() {
        return right;
    }

    void setData(const T&amp; d) {
        data = d;
    }

    void setLeft(BTNode&lt;T&gt;* l) {
        left = l;
    }

    void setRight(BTNode&lt;T&gt;* r) {
        right = r;
    }

    void add(const T&amp; d) {
        if (d &lt; data) {
            if (left)
                left-&gt;add(d);
            else
                setLeft(new BTNode&lt;T&gt;(d));
        }
        else if (d &gt; data) {
            if (right)
                right-&gt;add(d);
            else
                setRight(new BTNode&lt;T&gt;(d));
        }
    }

    BTNode&lt;T&gt;* findLCA(const T&amp; n1, const T&amp; n2) {
        if (n1 &lt; data &amp;&amp; n2 &lt; data)
            return left ? left-&gt;findLCA(n1, n2) : this;

        if (n1 &gt; data &amp;&amp; n2 &gt; data)
            return right ? right-&gt;findLCA(n1, n2) : this;

        return (n1 != data &amp;&amp; n2 != data) ? this : nullptr;
    }
};

template &lt;typename T&gt;
class BST 
{
private:
    BTNode&lt;T&gt; *root = nullptr;

public:    
    BST() = default;

    ~BST() {
        delete root;
    }

    void add(const T&amp; d) {
        if (root)
            root-&gt;add(d);
        else
            root = new BTNode&lt;T&gt;(d);
    }

    BTNode&lt;T&gt;* findLCA(const T&amp; n1, const T&amp; n2) {
        return root ? root-&gt;findLCA(n1, n2) : nullptr;
    }
};

template&lt;typename T&gt;
void displayLCA(BST&lt;T&gt; &amp;tree, const T&amp; n1, const T&amp; n2) {
    cout &lt;&lt; &quot;LCA(&quot; &lt;&lt; n1 &lt;&lt; &quot;,&quot; &lt;&lt; n2 &lt;&lt; &quot;) = &quot;;

    BTNode&lt;T&gt; *lca = tree.findLCA(n1, n2);
    if (lca)
        cout &lt;&lt; lca-&gt;getData();
    else
        cout &lt;&lt; &quot;not found&quot;;

    cout &lt;&lt; '\n';
}

int main()
{
    BST&lt;int&gt; tree;
    tree.add(4);
    tree.add(2);
    tree.add(7);
    tree.add(3);
    tree.add(6);
    tree.add(15);
    tree.add(5);

    displayLCA(tree, 5, 15);
    displayLCA(tree, 3, 5);

    return 0;
}
</code></pre>
